MAP
    NAME "GeoStylerDemo"
    SIZE 800 800
    EXTENT 26.668678 58.339241 26.796582 58.409410
    PROJECTION
        "EPSG:4326"
    END
    OUTPUTFORMAT
        NAME "geojson"
        DRIVER "OGR/GEOJSON"
        MIMETYPE "application/json; subtype=geojson; charset=utf-8"
        FORMATOPTION "FORM=SIMPLE"
        FORMATOPTION "STORAGE=memory"
        FORMATOPTION "LCO:NATIVE_MEDIA_TYPE=application/vnd.geo+json"
        FORMATOPTION "USE_FEATUREID=true" # ensure GeoJSON output has an id property
    END

    # we require an IMAGETYPE for the OpenLayers viewer
    # to avoid msDrawMap(): Image handling error. Unable to initialize image. msPrepareImage(): Image handling error. Unable to initialize image.
    IMAGETYPE PNG24

    # ensure symbol sizes are the same for any screen-size (see notes)
    RESOLUTION 90
    DEFRESOLUTION 90

    WEB
        IMAGEPATH "/etc/mapserver/tmp/"
        METADATA
            "ows_enable_request" "*"
            "ows_srs" "EPSG:4326 EPSG:3857"
            "ows_use_default_extent_for_getfeature" "false"
            "wfs_getfeature_formatlist" "geojson"
        END
    END

    # points
    INCLUDE "includes/notched-rect.sym"

    # lines
    INCLUDE "includes/arrow-wide.sym"

    # polygons
    INCLUDE "includes/fills.sym"
    INCLUDE "includes/square-spaced.sym"
    INCLUDE "includes/wave.sym"

    LAYER
        NAME "square-spaced"
        TYPE POLYGON
        STATUS OFF
        PROJECTION
            "EPSG:4326"
        END
        TEMPLATE "ttt"
        CONNECTIONTYPE OGR
        CONNECTION "data/osm/landuse_a.fgb"
        METADATA
            "gml_include_items" "all"
            "gml_featureid" "fid"
            "gml_types" "auto"
        END
        FILTER ("[fclass]" = "scrub")
        INCLUDE "includes/square-spaced.class"
    END

    LAYER
        NAME "fills"
        TYPE POLYGON
        # GEOMTRANSFORM (simplify([shape], 10))
        STATUS OFF
        PROJECTION
            "EPSG:4326"
        END
        TEMPLATE "ttt"
        CONNECTIONTYPE OGR
        CONNECTION "data/osm/landuse_a.fgb"
        METADATA
            "gml_include_items" "all"
            "gml_featureid" "fid"
            "gml_types" "auto"
        END
        INCLUDE "includes/fills.class"
    END

    LAYER
        NAME "wave"
        TYPE POLYGON
        STATUS OFF
        PROJECTION
            "EPSG:4326"
        END
        TEMPLATE "ttt"
        CONNECTIONTYPE OGR
        CONNECTION "data/osm/water_a.fgb"
        METADATA
            "gml_include_items" "all"
            "gml_featureid" "fid"
            "gml_types" "auto"
        END
        FILTER ("[fclass]" = "riverbank")
        INCLUDE "includes/wave.class"
    END

    LAYER
        NAME "notched-rect"
        TYPE POINT
        STATUS OFF
        PROJECTION
            "EPSG:4326"
        END
        TEMPLATE "ttt"
        CONNECTIONTYPE OGR
        CONNECTION "data/osm/pois.fgb"
        METADATA
            "gml_include_items" "all"
            "gml_featureid" "fid"
            "gml_types" "auto"
        END
        FILTER ("[fclass]" = "restaurant")
        INCLUDE "includes/notched-rect.class"
    END

    LAYER
        NAME "arrow-wide"
        TYPE LINE
        STATUS OFF
        PROJECTION
            "EPSG:4326"
        END
        TEMPLATE "ttt"
        CONNECTIONTYPE OGR
        CONNECTION "data/osm/roads.fgb"
        METADATA
            "gml_include_items" "all"
            "gml_featureid" "fid"
            "gml_types" "auto"
        END
        FILTER ("[fclass]" = "tertiary")
        INCLUDE "includes/arrow-wide.class"
    END

END